<?php use SwimlogStandalone\SwimComparison as SC;use SwimLogEvaluation\Workout; ?>
<section class="calendar-panel workout-page" aria-labelledby="comparison-title"><div class="workout-page-heading"><h2 id="comparison-title">Compare Swims</h2><a class="control" href="/?screen=log">Workout Log</a></div>
<?php if(is_wp_error($comparison)): ?><p role="alert"><?php echo esc_html($comparison->get_error_message()); ?></p><?php else:$m=$comparison; ?>
<p>Private comparison of recorded pool swims. Metrics use the plugin’s active-length rules. Rest, zero-distance lengths and missing measurements do not become active samples. Lower values describe less time or fewer recorded strokes; they do not alone establish better technique.</p>
<div class="comparison-summaries"><?php foreach($m['swims']as$i=>$s): ?><section><h3><?php echo $i===0?'Swim A':'Swim B'; ?></h3><dl class="workout-metrics"><?php foreach(array('Date'=>$s['start'],'Session distance'=>$s['distance_m']===null?'—':number_format_i18n($s['distance_m'],2).' m','Elapsed time'=>Workout::format_duration($s['elapsed_ms']),'Pool length'=>$s['pool']===null?'Unknown':$s['pool'].' '.$s['course'])as$label=>$value): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php endforeach; ?></dl><a class="control" data-workout-id="<?php echo esc_attr($s['id']); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url('/?workout='.$s['id']); ?>">View Swim <?php echo $i===0?'A':'B'; ?></a></section><?php endforeach; ?></div>
<?php foreach($m['warnings']as$warning): ?><p class="comparison-warning"><?php echo esc_html($warning); ?></p><?php endforeach; ?>
<?php if(!$m['strokes']): ?><p>No qualifying active-length evidence is available. Manual session totals alone cannot provide stroke-level pace, SWOLF or stroke counts.</p><?php endif; ?>
<?php foreach($m['strokes']as$stroke):$a=$m['swims'][0]['groups'][$stroke]??array();$b=$m['swims'][1]['groups'][$stroke]??array();$both=$a&&$b; ?>
<section class="comparison-stroke"><h3><?php echo esc_html(array('FR'=>'Freestyle','BR'=>'Breaststroke','BACK'=>'Backstroke','FLY'=>'Butterfly','MIXED'=>'Mixed','UNKNOWN'=>'Unknown stroke')[$stroke]??$stroke); ?></h3>
<div class="entry-compare"><table><caption><?php echo esc_html($stroke.' · A and B retain their recorded course units'); ?></caption><thead><tr><th scope="col">Metric</th><th scope="col">Swim A</th><th scope="col">Swim B</th><th scope="col">Difference</th></tr></thead><tbody>
<?php foreach(array('avg_pace_100_ms'=>array('Pace per 100','timed_lengths',$m['same_course']),'avg_swolf'=>array('SWOLF','swolf_lengths',$m['same_pool']),'avg_stroke_count'=>array('Strokes per length','stroke_count_lengths',$m['same_pool']))as$key=>$info):$allowed=$both&&$info[2];$av=$a[$key]??null;$bv=$b[$key]??null; ?>
<tr><th scope="row"><?php echo esc_html($info[0]); ?></th><?php foreach(array($a,$b)as$i=>$g): ?><td><?php echo esc_html(SC::value($g[$key]??null,$key).($key==='avg_pace_100_ms'?' / 100 '.$m['swims'][$i]['course']:'')); ?><br><small><?php echo esc_html(($g[$info[1]]??0).' sampled / '.($g['active_lengths']??0).' active lengths'); ?></small></td><?php endforeach; ?><td><?php echo esc_html(SC::delta($av,$bv,$key,$allowed)); ?></td></tr>
<?php endforeach; ?>
<tr><th scope="row">Matching active distance</th><?php foreach(array($a,$b)as$i=>$g): ?><td><?php echo esc_html(isset($g['distance_native'])?number_format_i18n($g['distance_native'],2).' '.$m['swims'][$i]['course']:'—'); ?></td><?php endforeach; ?><td>Recorded workload context</td></tr>
</tbody></table></div>
<div class="comparison-graphics"><?php foreach(array('avg_pace_100_ms'=>'Pace per 100','avg_swolf'=>'SWOLF','avg_stroke_count'=>'Strokes per length')as$key=>$title): ?><section><h4><?php echo esc_html($title); ?></h4><?php if($both&&($key==='avg_pace_100_ms'?$m['same_course']:$m['same_pool'])):echo SC::chart($a[$key],$b[$key],$key,$stroke.' · '.$title.' · A blue, B brown; exact values above');else: ?><p>Paired chart unavailable for these courses, pool lengths or stroke samples.</p><?php endif; ?></section><?php endforeach; ?></div></section>
<?php endforeach;endif; ?></section>
